import { createElement, useMemo, type CSSProperties, type ReactNode } from 'react'

// Only the SVG generated by our ECharts configuration reaches this converter.
// It does not accept imported SVG, markup from the editor or HTML fragments.
const elements = new Set([
  'svg',
  'g',
  'path',
  'rect',
  'circle',
  'ellipse',
  'line',
  'polyline',
  'polygon',
  'text',
  'tspan',
  'defs',
  'clipPath',
  'linearGradient',
  'radialGradient',
  'stop',
  'pattern',
  'style',
])

function cssProperties(value: string): CSSProperties {
  const style: Record<string, string> = {}
  for (const declaration of value.split(';')) {
    const colon = declaration.indexOf(':')
    if (colon < 0) continue
    const name = declaration
      .slice(0, colon)
      .trim()
      .replace(/-([a-z])/g, (_, character: string) => character.toUpperCase())
    if (name) style[name] = declaration.slice(colon + 1).trim()
  }
  return style
}

export function chartSvgChildren(svg: string, scope: string): ReactNode[] {
  if (typeof DOMParser === 'undefined')
    throw new Error('O gráfico vetorial precisa de um navegador para ser preparado.')
  const doc = new DOMParser().parseFromString(svg, 'image/svg+xml')
  if (doc.querySelector('parsererror'))
    throw new Error('Não foi possível interpretar o gráfico vetorial.')
  const names = new Map<string, string>()
  for (const element of doc.querySelectorAll('[id],[class]')) {
    const id = element.getAttribute('id')
    if (id) names.set(id, `${scope}-${id}`)
    for (const name of (element.getAttribute('class') ?? '').split(/\s+/).filter(Boolean))
      names.set(name, `${scope}-${name}`)
  }
  for (const style of doc.querySelectorAll('style')) {
    for (const match of (style.textContent ?? '').matchAll(/@keyframes\s+([\w-]+)/g))
      names.set(match[1], `${scope}-${match[1]}`)
  }
  const rewrite = (value: string): string =>
    value.replace(/[A-Za-z_][\w-]*/g, (token) => names.get(token) ?? token)
  let count = 0
  const convert = (node: Node, key: number): ReactNode => {
    if (++count > 12_000)
      throw new Error(
        'O gráfico tem elementos demais para ser exibido. Divida os dados em mais slides.',
      )
    if (node.nodeType === 3 || node.nodeType === 4) return node.textContent
    if (node.nodeType !== 1) return null
    const element = node as Element
    if (!elements.has(element.localName))
      throw new Error(`O gráfico contém um elemento não suportado: ${element.localName}.`)
    const props: Record<string, unknown> = { key }
    for (const attribute of Array.from(element.attributes)) {
      const name = attribute.name
      if (/^on/i.test(name) || name === 'xmlns' || name.startsWith('xmlns:')) continue
      if ((name === 'href' || name === 'xlink:href') && !attribute.value.startsWith('#')) continue
      const value = /^(id|class|clip-path|mask|fill|stroke|filter|href|xlink:href|style)$/.test(
        name,
      )
        ? rewrite(attribute.value)
        : attribute.value
      if (name === 'style') props.style = cssProperties(value)
      else {
        const reactName =
          name === 'class'
            ? 'className'
            : name === 'xlink:href'
              ? 'xlinkHref'
              : name === 'xml:space'
                ? 'xmlSpace'
                : /^(data-|aria-)/.test(name)
                  ? name
                  : name.replace(/-([a-z])/g, (_, character: string) => character.toUpperCase())
        props[reactName] = value
      }
    }
    if (element.localName === 'style')
      return createElement('style', props, rewrite(element.textContent ?? ''))
    return createElement(element.localName, props, ...Array.from(element.childNodes).map(convert))
  }
  return Array.from(doc.documentElement.childNodes).map(convert)
}

export function InlineChartSvg({
  svg,
  scope,
  x,
  y,
  width,
  height,
  type,
  animated,
}: {
  svg: string
  scope: string
  x: number
  y: number
  width: number
  height: number
  type: string
  animated: boolean
}) {
  const children = useMemo(() => chartSvgChildren(svg, scope), [svg, scope])
  return (
    <svg
      x={x}
      y={y}
      width={width}
      height={height}
      viewBox={`0 0 ${width} ${height}`}
      data-chart-type={type}
      data-chart-animated={String(animated)}
    >
      {children}
    </svg>
  )
}
